'use strict';

// MODULES //

var isObject = require( '@stdlib/assert/is-object' );
var hasProp = require( '@stdlib/assert/has-property' );
var AggregateFacetTransform = require( '@stdlib/plot/vega/transform/aggregate/facet/ctor' );


// MAIN //

/**
* Tests whether an input value is a aggregate-facet transform instance.
*
* @param {*} value - value to test
* @returns {boolean} boolean indicating whether an input value is a aggregate-facet transform instance
*
* @example
* var AggregateFacetTransform = require( '@stdlib/plot/vega/transform/aggregate/facet/ctor' );
*
* var v = new AggregateFacetTransform();
* var bool = isAggregateFacetTransform( v );
* // returns true
*
* bool = isAggregateFacetTransform( {} );
* // returns false
*
* bool = isAggregateFacetTransform( 'foo' );
* // returns false
*/
function isAggregateFacetTransform( value ) {
	return (
		value instanceof AggregateFacetTransform ||

		// The following is a set of rather imperfect heuristics for handling instances originating in a different realm...
		(
			isObject( value ) &&
			hasProp( value, 'cross' )
		)
	);
}


// EXPORTS //

module.exports = isAggregateFacetTransform;
